const COURSES = { 1: '리액트 입문', 2: 'CSS 레이아웃' };

function loadCourse(id) {
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      if (COURSES[id]) {
        resolve({ id, name: COURSES[id] });
      } else {
        reject(new Error('코스를 찾지 못했습니다'));
      }
    }, 60);
  });
}

// 이 함수는 그대로 두세요
function report(id) {
  return loadCourse(id)
    .then((c) => '성공: ' + c.id + '번 ' + c.name)
    .catch((e) => '실패: ' + e.message);
}
